def poblar_y_limpiar_duplicados(apps, schema_editor):
    Proceso = apps.get_model("organizacion", "Proceso")

    # 1. Poblar nombre_normalizado para todas las filas existentes
    for p in Proceso.objects.all():
        norm = normalizar_texto(p.nombre)
        if p.nombre_normalizado != norm:
            p.nombre_normalizado = norm
            p.save(update_fields=["nombre_normalizado"])

    # 2. Limpiar duplicados en procesos raíz (padre is None)
    # Conserva el más antiguo, mueve sus subprocesos únicos,
    # borra primero los subprocesos repetidos y luego el padre duplicado
    raices_grupos = defaultdict(list)
    for p in Proceso.objects.filter(padre__isnull=True).order_by("created_at", "id"):
        key = (p.empresa_id, p.tipo, p.nombre_normalizado)
        raices_grupos[key].append(p)

    for key, items in raices_grupos.items():
        if len(items) <= 1:
            continue
        canonical = items[0]  # El más antiguo
        duplicados = items[1:]

        for dup in duplicados:
            # Mapa de subprocesos ya existentes en el padre canónico
            sub_canonical_map = {
                sub.nombre_normalizado: sub
                for sub in Proceso.objects.filter(padre=canonical)
            }

            for sub_dup in Proceso.objects.filter(padre=dup).order_by("created_at", "id"):
                if sub_dup.nombre_normalizado in sub_canonical_map:
                    # Subproceso repetido: reasignar referencias y borrar
                    sub_canon = sub_canonical_map[sub_dup.nombre_normalizado]
                    _reasignar_referencias(apps, sub_dup.id, sub_canon.id)
                    sub_dup.delete()
                else:
                    # Subproceso único: moverlo al padre canónico
                    sub_dup.padre = canonical
                    sub_dup.save(update_fields=["padre"])
                    sub_canonical_map[sub_dup.nombre_normalizado] = sub_dup

            # Borrar el padre duplicado después de mover/borrar sus hijos
            _reasignar_referencias(apps, dup.id, canonical.id)
            dup.delete()

    # 3. Limpieza de duplicados entre subprocesos directos (mismo padre)
    sub_grupos = defaultdict(list)
    for p in Proceso.objects.filter(padre__isnull=False).order_by("created_at", "id"):
        key = (p.empresa_id, p.tipo, p.padre_id, p.nombre_normalizado)
        sub_grupos[key].append(p)

    for key, items in sub_grupos.items():
        if len(items) <= 1:
            continue
        canonical = items[0]
        duplicados = items[1:]
        for dup in duplicados:
            _reasignar_referencias(apps, dup.id, canonical.id)
            dup.delete()


